    struct vm_area_struct *vma;

    while (!list_empty(&mm_slots_list)) {
        slot = list_entry(mm_slots_list.next, struct mm_slot, mm_list);
        list_del(&slot->mm_list);

        for (vma = slot->mm->mmap; vma; vma = vma->vm_next) {
            if (vma->vm_flags & VM_MERGEABLE) {
                *page = get_next_mergeable_page(vma);
