struct rmap_item *get_next_rmap_item(struct page **page) {
    struct mm_slot *slot;
    struct vm_area_struct *vma;
    struct rmap_item *rmap;

    if (list_empty(&mm_slots_list))
        return NULL;

    slot = list_entry(mm_slots_list.next, struct mm_slot, list);
    list_move_tail(&slot->list, &free_mm_slots_list);

    for (vma = slot->mm->mmap; vma; vma = vma->vm_next) {
        if (vma->vm_flags & VM_MERGEABLE) {
            *page = vma->anon_vma->page;
            if (*page) {
                rmap = get_rmap_from_page(*page);
                return rmap;
            }
        }
    }

    cleanup_mm_slot(slot);
    return NULL;
}

struct rmap_item *get_next_rmap_item(struct page **page) {
    struct mm_slot *slot;
    struct vm_area_struct *vma;
    struct mm_struct *mm;

    if (list_empty(&mm_list)) {
        return NULL;
    }

    slot = list_first_entry(&mm_list, struct mm_slot, mm_list);
    mm = slot->mm;

    for (vma = mm->mmap; vma; vma = vma->vm_next) {
        if (vma->vm_flags & VM_MERGEABLE) {
            struct page *p = find_mergeable_page(vma);
            if (p) {
                *page = p;
                return get_rmap_item_from_page(p);
            }
        }
    }

    cleanup_mm_slot(slot);
    return NULL;
}

struct rmap_item *get_next_rmap_item(struct page **page) {
    struct mm_slot *slot;
    struct vm_area_struct *vma;
    struct rmap_item *item = NULL;

    if (list_empty(&mm_slots_list))
        return NULL;

    slot = list_first_entry(&mm_slots_list, struct mm_slot, mm_list);
    list_del(&slot->mm_list);

    for (vma = slot->mm->mmap; vma; vma = vma->vm_next) {
        if (vma->vm_flags & VM_MERGEABLE) {
            if (find_mergeable_page(vma, page)) {
                item = get_rmap_item_from_page(*page);
                break;
            }
        }
    }

    kfree(slot);

    return item;
}

